    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ==============================

    assert( self.catJumpBtn )
    self.catJumpBtnGO = self.catJumpBtn.gameObject

    assert( self.PC and self.Mobile and self.PcTipsNode )

    print("koko - isWindowsPlatform: " .. tostring(DreamSpaceStates.isWindowsPlatform) )
    if DreamSpaceStates.isWindowsPlatform == true then 
        KTool.SetActive( self.PC.gameObject,      true )
        KTool.SetActive( self.Mobile.gameObject,  false )

        -- 隐藏 LeftJoystick: -- todo: 目前 LeftJoystick 会跟着 RoleControllerRootCanvas 一起被隐藏, 不需要在此操作了
