        -- if joystickCanvasGroup then 
        --     joystickCanvasGroup.alpha = 0

        --     -- pc包中, 这个节点意外没有被上面的 alpha=0 覆盖到, 手动关闭下: 
        --     local BackGroundCenterTF = joystickCanvasGroup.transform:Find("BackGroundCenter")
        --     if BackGroundCenterTF then
        --         print("koko - 找到 BackGroundCenter")
        --         KTool.SetActive( BackGroundCenterTF.gameObject, false )
        --     end  

        -- else 
        --     printError("koko - joystick 上没绑定 CanvasGroup")
        -- end
        -- print("koko- joystickCanvasGroup.alpha = " .. tostring(joystickCanvasGroup.alpha) )

    else 
        KTool.SetActive( self.PC.gameObject,      false )
        KTool.SetActive( self.Mobile.gameObject,  true )
    end 

    KTool.SetActive( self.PC.PcTipsNode,      false )

