    self:FreshCatJumpButton()
end




function UIMain_Manager:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end



function UIMain_Manager:Update()
    self:FreshCatJumpButton()


    if DreamSpaceStates.isWindowsPlatform == true then 
    
        if Input.GetKeyDown(KeyboardInfo.PcTipsKey) then 
            print("koko - 按下 P")

            -- === PC 版 信息提示面板 ===:
            if DreamSpaceStates.IsSubPanelFreeInPC() == true then

                if DreamSpaceStates.currentOpenPanelTypeInPC == DreamSpaceStates.CurrentOpenPanelTypeInPC.None then 
                    -- 开:
                    KTool.SetActive( self.PcTipsNode.gameObject, true )
                    DreamSpaceStates.LockInput_ByCount( DreamSpaceStates.InputLockState.Lock ) -- 希望禁止玩家输入
                    DreamSpaceStates.currentOpenPanelTypeInPC = DreamSpaceStates.CurrentOpenPanelTypeInPC.PCTipsPanel

                elseif DreamSpaceStates.currentOpenPanelTypeInPC == DreamSpaceStates.CurrentOpenPanelTypeInPC.PCTipsPanel then 
                    -- 关:
                    KTool.SetActive( self.PcTipsNode.gameObject, false )
                    DreamSpaceStates.LockInput_ByCount( DreamSpaceStates.InputLockState.Unlock ) -- 解除禁止:玩家输入
                    DreamSpaceStates.currentOpenPanelTypeInPC = DreamSpaceStates.CurrentOpenPanelTypeInPC.None    
                end
            end


        elseif Input.GetKeyDown(KeyCode.LeftControl) or Input.GetKeyDown(KeyCode.RightControl) then 
            print("koko - 按下 Ctrl")

            -- === PC 版 猫 走路 / 跑步 切换 ===:
            if DreamSpaceStates.IsSubPanelFreeInPC() == true then

                if DreamSpaceStates.currentOpenPanelTypeInPC == DreamSpaceStates.CurrentOpenPanelTypeInPC.None then 
                    if self._isWalk ~= true then 
                        self._isWalk = true 
                        InputManager.SetMoveInputMagnitudeConstraint( nil, 0.2 ) -- 只能走路
                        GameUtils.Toast(localize("切换为走路模式", 2.0))
                    else 
                        self._isWalk = false 
                        InputManager.SetMoveInputMagnitudeConstraint( 0.0, 1.0 ) -- 解除 "只能走路" 的限制
                        GameUtils.Toast(localize("切换为跑步模式", 2.0))
                    end 
                end
            end
        end 
    end 


end



function UIMain_Manager:FreshCatJumpButton()
    if DreamSpaceStates.IsShowJumpUI ~= self.lastIsShowJumpUI then 
        self.lastIsShowJumpUI = DreamSpaceStates.IsShowJumpUI
        KTool.SetActive( self.catJumpBtnGO, DreamSpaceStates.IsShowJumpUI )

        -- 每次亮起, 都主动播一次 idle 让按钮状态归零:
        if DreamSpaceStates.IsShowJumpUI == true then 
            DreamSpaceLuaUtils.PlayAnimation(self.catJumpBtnGO, ButtonIdle )
        end 

    end
end









return UIMain_Manager

